from pathlib import Path
root=Path.cwd(); s=(root/'scripts/run_s15_history.py').read_text()
s=s.replace('S15 history-only CUT3R inference; exactly twenty RGB inputs, no target query.', 'S17B fixed 512 DPT CUT3R inference; exactly two pre-exposed RGB inputs, no target query.')
s=s.replace("[1, 224, 224, 3]", "[1, 384, 512, 3]").replace("[1, 224, 224]", "[1, 384, 512]")
s=s.replace("'7a7d83e47f822e040980c8f5aff4c15aa94366d469d3ceae51fa30cc2f62327d'", "'45f7e98a0a64dbeb54901ae2b878cd8cd125f20a4497316483f0bd6f109f8103'")
s=s.replace("IMAGE_EXTENSIONS =", "CHECKPOINT_BYTES = 3173761006\nHISTORY_SHA256 = [\n    '7caa6f1b9fd1ac5b6938812682c55e3d7926a1348c7554c23e1012b47759cc39',\n    '77bebdb3ac737221ef05a4404a1124676bcff536dbffb6e197b59bcdf811ae',\n]\nIMAGE_EXTENSIONS =")
# Correct exact second source digest from S15A frozen manifest instead of transcribing it.
import json
m=json.loads((root/'docs/S15A_HISTORY_EXECUTION_MANIFEST.json').read_text())
s=s.replace('77bebdb3ac737221ef05a4404a1124676bcff536dbffb6e197b59bcdf811ae',m['history_images'][1]['sha256'])
s=s.replace('dict(history_count=20,', 'dict(history_count=2,').replace("size=[224, 224], dtype='float32',", "size=[384, 512], loader_size=512, raw_image_size=[640, 480],\n    head_type='dpt', patch_image_size=[512, 512], dtype='float32',")
s=s.replace("'s15-history-manifest-v1'", "'s17b-dpt-two-frame-manifest-v1'")
s=s.replace("len(history) == 20 and [x['index'] for x in history] == list(range(20)), 'Ordered history indices 0..19'", "len(history) == 2 and [x['index'] for x in history] == [0, 1], 'Ordered history indices 0/1'")
s=s.replace("require(len(set(paths)) == 20, 'Distinct twenty RGB files')", "require(len(set(paths)) == 2, 'Distinct two RGB files')\n    require([x['sha256'] for x in history] == HISTORY_SHA256, 'Exact S15A original RGB indices 0/1')")
s=s.replace("require(len(images) == 20, 'Official loader returned twenty histories')", "require(len(images) == 2, 'Official loader returned two histories')")
s=s.replace("[1, 3, 224, 224]", "[1, 3, 384, 512]").replace("[[224, 224]]", "[[384, 512]]").replace("(1, 224, 224, 6)", "(1, 384, 512, 6)")
s=s.replace("len(history['pred']) == 20, 'Twenty prediction entries'", "len(history['pred']) == 2, 'Two prediction entries'")
s=s.replace("len(snapshots) == 21 and len(snapshots[-1]) == 5, 'Twenty updates plus initial state'", "len(snapshots) == 3 and len(snapshots[-1]) == 5, 'Two updates plus initial state'")
s=s.replace("[20, 4, 4]", "[2, 4, 4]").replace("(20, 1)", "(2, 1)").replace("['history_frames_saved'] = 20", "['history_frames_saved'] = 2")
s=s.replace("'s15-history-run-v1'", "'s17b-dpt-two-frame-run-v1'")
s=s.replace("history_ray_encoder_calls=0, history_frames_saved=0, query_calls=0)", "history_ray_encoder_calls=0, history_frames_saved=0, query_calls=0,\n            history_ray_encoder_frames=0, supplied_ray_frames=0,\n            history_encoder_first_block_calls=0, history_encoder_last_block_calls=0)")
s=s.replace("phase('pre_run_identity')", "require(Path(m['checkpoint']).stat().st_size == CHECKPOINT_BYTES, 'Complete 512 DPT checkpoint size')\n        report['checkpoint_identity'] = dict(path=m['checkpoint'], sha256=CHECKPOINT_SHA256, bytes=CHECKPOINT_BYTES)\n        phase('pre_run_identity')")
s=s.replace("phase('decode_twenty_history_rgb_only')", "phase('decode_two_history_rgb_only')").replace("len(decoded) < 20", "len(decoded) < 2")
s=s.replace("image.load()\n            decoded.append(p)", "require(list(image.size) == m['contract']['raw_image_size'] and image.mode == 'RGB', 'Frozen native Bonn RGB properties')\n            image.load()\n            decoded.append(p)")
s=s.replace("load_images(paths, size=224, verbose=False)", "load_images(paths, size=512, verbose=False)").replace("'Exactly twenty RGB decodes in frozen order'", "'Exactly two RGB decodes in frozen order'")
s=s.replace("views = make_views(images, torch)\n        phase('load_existing_checkpoint')", "views = make_views(images, torch)\n        report['processed_input_shapes'] = [list(v['img'].shape) for v in views]\n        report['processed_true_shapes'] = [v['true_shape'].tolist() for v in views]\n        report['history_flags'] = [{k: bool(v[k].item()) for k in FLAGS} for v in views]\n        phase('load_existing_checkpoint')")
s=s.replace("require(model.head_type == 'linear' and list(model.patch_embed.img_size) == [224, 224], 'Pinned architecture')", "require(model.head_type == 'dpt' and list(model.patch_embed.img_size) == [512, 512], 'Pinned 512 DPT architecture')\n        require(type(model.patch_embed).__name__ == 'PatchEmbedDust3R', 'Official loader normalized image patch class')\n        require(type(model.downstream_head).__name__ == 'DPTPts3dPose', 'Actual DPT six-head implementation')\n        require(len(model.enc_blocks) == 24, 'Pinned image encoder depth')")
s=s.replace("report.update(checkpoint_all_keys_matched=True, weights_only=True)", "report.update(checkpoint_all_keys_matched=True, weights_only=True,\n            architecture=dict(head_type=model.head_type, output_mode=model.output_mode,\n                image_patch_class=type(model.patch_embed).__name__,\n                ray_patch_class=type(model.patch_embed_ray_map).__name__,\n                patch_image_size=list(model.patch_embed.img_size),\n                downstream_head_class=type(model.downstream_head).__name__,\n                encoder_blocks=len(model.enc_blocks), parameters=sum(p.numel() for p in model.parameters())),\n            checkpoint_unsafe_globals=unsafe, encoder_observations=[])" )
s=s.replace("report['counters']['history_image_encoder_frames'] += int(inputs[0].shape[0])", "report['counters']['history_image_encoder_frames'] += int(inputs[0].shape[0])\n            report['encoder_observations'].append(dict(kind='image_patch', input_shape=list(inputs[0].shape), dtype=str(inputs[0].dtype), output_token_shape=list(result[0].shape)))")
s=s.replace("report['counters']['history_ray_encoder_calls'] += 1\n        handles = [model.patch_embed.register_forward_hook(image_hook), model.patch_embed_ray_map.register_forward_hook(ray_hook)]", "report['counters']['history_ray_encoder_calls'] += 1\n            report['counters']['history_ray_encoder_frames'] += int(inputs[0].shape[0])\n            report['encoder_observations'].append(dict(kind='dummy_ray_patch', input_shape=list(inputs[0].shape), dtype=str(inputs[0].dtype), all_zero=bool((inputs[0] == 0).all()), output_token_shape=list(result[0].shape)))\n        def boundary_hook(kind):\n            def hook(module, inputs, result):\n                report['counters']['history_encoder_' + kind + '_block_calls'] += 1\n                report['encoder_observations'].append(dict(kind='image_encoder_' + kind + '_block', input_shape=list(inputs[0].shape), dtype=str(inputs[0].dtype)))\n            return hook\n        handles = [model.patch_embed.register_forward_hook(image_hook), model.patch_embed_ray_map.register_forward_hook(ray_hook),\n            model.enc_blocks[0].register_forward_hook(boundary_hook('first')), model.enc_blocks[-1].register_forward_hook(boundary_hook('last'))]")
s=s.replace("['history_image_encoder_frames'] == 20", "['history_image_encoder_frames'] == 2")
s=s.replace("and report['counters']['history_ray_encoder_calls'] == 1 and report['counters']['query_calls'] == 0, 'History-only encoder/call budget')", "and report['counters']['history_ray_encoder_calls'] == 1\n                and report['counters']['history_ray_encoder_frames'] == 1\n                and report['counters']['history_encoder_first_block_calls'] == 1\n                and report['counters']['history_encoder_last_block_calls'] == 1\n                and report['counters']['supplied_ray_frames'] == 0\n                and report['counters']['query_calls'] == 0, 'History-only encoder/call budget')\n        obs = {o['kind']: o for o in report['encoder_observations']}\n        require(obs['image_patch']['input_shape'] == [2, 3, 384, 512] and obs['image_patch']['output_token_shape'] == [2, 768, 1024], 'Actual two-image encoder input/token count')\n        require(obs['dummy_ray_patch']['input_shape'] == [1, 6, 384, 512] and obs['dummy_ray_patch']['all_zero'], 'Official zero dummy ray path; no supplied rays')\n        require(all(obs['image_encoder_' + kind + '_block']['input_shape'] == [2, 768, 1024] for kind in ['first', 'last']), 'Actual image backbone traversal')")
assert '20' not in s[s.index('def execute_history'):s.index('def main')]
(root/'scripts/run_s17b_dpt_history.py').write_text(s)
